import { IMetric } from 'entities/Report';
import { formatDate } from 'shared/utils';

export const transformData = (startDate: Date, endDate: Date, data: IMetric[]) => {
	const dataMap = data.reduce(
		(acc, item) => {
			return {
				...acc,
				[item.date]: {
					...item,
					approved_amount: +item.approved_amount,
					actions_count: +item.actions_count,
					count: +item.count,
					cr: +item.cr,
					ar: +item.ar,
					epc: +item.epc,
					epl: +item.epl,
					amount: +item.amount,
					clicks_count: +item.clicks_count,
					approved_actions_count: +item.approved_actions_count,
				},
			};
		},
		{} as Record<string, IMetric>,
	);

	const dateArray = [];
	const currentDate = startDate;

	while (currentDate <= endDate) {
		dateArray.push(
			dataMap[formatDate(currentDate, 'iso') || ''] || {
				date: formatDate(currentDate, 'iso'),
				approved_amount: 0,
				actions_count: 0,
				count: 0,
				cr: 0,
				ar: 0,
				epc: 0,
				epl: 0,
				amount: 0,
				clicks_count: 0,
				approved_actions_count: 0,
			},
		);
		currentDate.setUTCDate(currentDate.getUTCDate() + 1);
	}

	return dateArray;
};
