import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';

import { Area } from '@ant-design/charts';

import { Flex, Select, theme, Typography } from 'antd';
import cn from 'classnames';

import { IMetric, transformData, useReportsSlice } from 'entities/Report';
import { EFilters, prepareDate, ReportsChartFilters } from 'features/Filters';
import { EMainRoutes } from 'shared/typings';
import { EmptyState } from 'shared/ui';
import { formatDate, formatNumber } from 'shared/utils';

import styles from './ReportChart.module.scss';

interface IReportChartProps extends HTMLAttributes<HTMLDivElement> {
	data?: IMetric[];
	isFetching: boolean;
	isDasboard?: boolean;
}

export const ReportChart: FC<IReportChartProps> = ({ data, isDasboard, isFetching, ...props }) => {
	const { t } = useTranslation();
	const {
		token: { colorBorderSecondary, colorBgBase },
	} = theme.useToken();

	const { chartFilters } = useReportsSlice();
	const searchParams = new URLSearchParams(
		Object.keys(chartFilters).reduce((acc, key) => {
			return chartFilters[key as EFilters] ? { ...acc, [key]: chartFilters[key as EFilters] } : acc;
		}, {}),
	);

	const hasData = !!data?.length;
	const [chartType, setChartType] = useState<
		'cr' | 'ar' | 'epc' | 'epl' | 'approved_amount' | 'amount' | 'actions_count' | 'clicks_count'
	>(isDasboard ? 'approved_amount' : 'cr');

	const chartNames = {
		cr: t('CR'),
		ar: t('AR'),
		epc: t('EPC'),
		epl: t('EPL'),
		approved_amount: t('Доход'),
		amount: t('Открытая сумма'),
		actions_count: t('Действия'),
		clicks_count: t('Клики'),
	};

	const config = {
		data: transformData(
			isDasboard
				? prepareDate(new Date(), 29)
				: new Date(searchParams.get(EFilters.DATE_AFTER) || data?.[data.length - 1]?.date || ''),
			searchParams.get(EFilters.DATE_BEFORE) ? new Date(searchParams.get(EFilters.DATE_BEFORE) || '') : new Date(),
			data || [],
		).map((item) => ({
			...item,
			date: new Date(item.date),
		})),
		xField: 'date',
		yField: chartType,
		height: isDasboard ? 246 : 400,
		axis: {
			x: {
				labelFormatter: (d: Date) => formatDate(d, 'chart'),
				labelAlign: 'horizontal',
				labelSpacing: 10,
				labelAutoRotate: false,
			},
			y: {
				labelFormatter: (v: string) => formatNumber(v),
			},
		},
		paddingRight: 16,
		style: {
			fillOpacity: 1,
			fill: 'linear-gradient(90deg, rgba(19, 194, 194, 0.30) 0%, rgba(19, 194, 194, 0.00) 100%)',
			lineWidth: 0,
			stroke: '#13C2C2',
		},
		line: {
			size: 3,
			style: {
				stroke: '#13C2C2',
				strokeWidth: 1,
			},
		},
		/*point: {
			shapeField: 'circle',
			sizeField: 2,
			style: {
				stroke: '#13C2C2',
				fill: '#13C2C2',
			},
		},*/
		tooltip: {
			title: {
				field: 'date',
				valueFormatter: (d: Date) => `${formatDate(d, 'day')}, ${formatDate(d, 'medium')}`,
			},
			items: [
				{
					color: '#13C2C2',
					name: chartNames[chartType] || chartType.toUpperCase(),
					field: chartType,
					valueFormatter: (v: string) => formatNumber(v),
				},
			],
		},
	};

	return (
		<div
			{...props}
			className={styles.card}
			style={{ ...props.style, borderColor: colorBorderSecondary, backgroundColor: colorBgBase }}>
			<Flex vertical>
				{isDasboard && (
					<div className={cn(styles.topbar, { [styles.dasboard]: isDasboard })}>
						<Typography.Title level={4} style={{ margin: 0 }}>
							{t('Действия (Заявки, Leads)')}
						</Typography.Title>
						<Link to={`/${EMainRoutes.REPORTS}`}>{t('Статистика')}</Link>
					</div>
				)}
				<div className={cn(styles.filters, { [styles.dasboard]: isDasboard })}>
					{!isDasboard && <ReportsChartFilters isDashboard={false} />}

					<Select className={styles.type} size="small" onChange={(v) => setChartType(v)} value={chartType}>
						{isDasboard && <Select.Option value="approved_amount">{t('Доход')}</Select.Option>}
						{isDasboard && <Select.Option value="amount">{t('Открытая сумма')}</Select.Option>}
						{isDasboard && <Select.Option value="actions_count">{t('Действия')}</Select.Option>}
						{isDasboard && <Select.Option value="clicks_count">{t('Клики')}</Select.Option>}
						{!isDasboard && <Select.Option value="cr">CR</Select.Option>}
						<Select.Option value="ar">AR</Select.Option>
						{!isDasboard && <Select.Option value="epc">EPC</Select.Option>}
						<Select.Option value="epl">EPL</Select.Option>
					</Select>

					{isDasboard && <ReportsChartFilters isDashboard={true} />}
				</div>

				{!hasData && !isFetching && <EmptyState title={t('Пока нет статистики')} />}

				{hasData && (
					<div className={styles.chart}>
						<div className={cn(styles.inner, { [styles.dasboard]: isDasboard })}>
							<Area {...config} />
						</div>
					</div>
				)}
			</Flex>
		</div>
	);
};
