export const prepareDate = (date: Date, diff: number = 0) => {
	date.setHours(0);
	date.setMinutes(0);
	date.setSeconds(0);
	date.setMilliseconds(0);
	diff && date.setDate(date.getDate() - diff);

	return date;
};

export const prepareMonth = (date: Date, diff: number = 0) => {
	return date.getMonth() + diff + 1;
};
