import { HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Select } from 'antd';
import cn from 'classnames';

import { useReportsSlice } from 'entities/Report';
import { EFilters, useFilters } from 'features/Filters';

import styles from './ReportsChartFilters.module.scss';

export interface IReportsChartFiltersProps extends HTMLAttributes<HTMLDivElement> {
	isDashboard?: boolean;
}

export const ReportsChartFilters = ({ className, isDashboard, ...props }: IReportsChartFiltersProps) => {
	const { t } = useTranslation();
	const { sourcesOptions, offersOptions } = useFilters();
	const { chartFilters, setFilter } = useReportsSlice();

	return (
		<div {...props} className={cn(className, styles.filters, { [styles.dashboard]: isDashboard })}>
			<Select
				size="small"
				onChange={(value) => setFilter({ name: EFilters.SOURCE_ID, value })}
				value={chartFilters[EFilters.SOURCE_ID]}
				options={sourcesOptions}
				showSearch
				optionFilterProp="label"
				placeholder={t('Выбрать площадку')}
				allowClear
			/>

			{!isDashboard && (
				<Select
					size="small"
					onChange={(value) => setFilter({ name: EFilters.OFFER_ID, value })}
					value={chartFilters[EFilters.OFFER_ID]}
					options={offersOptions}
					showSearch
					optionFilterProp="label"
					placeholder={t('Выбрать оффер')}
					allowClear
				/>
			)}
		</div>
	);
};

export default ReportsChartFilters;
